const publishButton=document.querySelector('#publish-github');
const publishEndpoint=document.querySelector('#publish-endpoint');
const publishPassword=document.querySelector('#publish-password');
const publishStatus=document.querySelector('#publish-status');
const TEST_WORKER_URL=String(window.COOKIES_CAKES_MENU_WORKER_URL||'').replace(/\/$/,'');
publishEndpoint.value=TEST_WORKER_URL;

function publishMessage(message,isError=false){publishStatus.textContent=message;publishStatus.style.color=isError?'#9a254d':'';}
function serialiseMenu(){const selection=menuItemOrder.filter(id=>weeklySelection.has(id));return `window.menuCatalogue = ${JSON.stringify(menuCatalogue,null,2)};\n\nwindow.weeklyMenuSelection = ${JSON.stringify(selection,null,2)};\n\nwindow.menuItemOrder = ${JSON.stringify(menuItemOrder,null,2)};\n\nwindow.menuCategories = ${JSON.stringify(menuCategories,null,2)};\n`;}
function toBase64(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(reader.error);reader.readAsDataURL(file);});}
async function imagesForPublish(){const images=[];for(const [itemId,pending] of pendingPhotos){const item=menuCatalogue.find(entry=>entry.id===itemId);if(!item)continue;if(!/^images\/[a-z0-9][a-z0-9._-]*$/i.test(pending.path))throw new Error('An image path is not valid.');item.image=pending.path;images.push({path:pending.path,content:await toBase64(pending.file)});}return images;}
async function publishToGitHub(){try{publishButton.disabled=true;publishMessage('Uploading the menu to GitHub…');const endpoint=publishEndpoint.value.trim();if(!endpoint)throw new Error('This manager is missing its Worker address.');const result=await fetch(`${endpoint}/api/publish-menu`,{method:'POST',headers:{'Content-Type':'application/json','X-Menu-Publish-Password':publishPassword.value},body:JSON.stringify({menuData:serialiseMenu(),images:await imagesForPublish()})});const body=await result.json();if(!result.ok)throw new Error(body.error||'Publishing failed.');publishPassword.value='';pendingPhotos.clear();renderLibrary();renderActiveItems();setStatus(saveStatus,'Published successfully. Your menu is now rebuilding on the website.');publishMessage(`Published to GitHub — commit ${body.commit.slice(0,7)}.`);}catch(error){const message=error&&error.message==='Failed to fetch'?'Could not reach the configured Worker. Check that it is deployed and publicly available.':error.message||'Publishing failed.';publishMessage(message,true);}finally{publishButton.disabled=false;}}
publishButton.addEventListener('click',()=>{if(!publishPassword.value){publishMessage('Enter the publish password first.',true);return;}try{prepareMenuForPublish();}catch(error){publishMessage(error.message||'Check your menu before publishing.',true);return;}publishToGitHub();});
publishPassword.addEventListener('keydown',event=>{if(event.key!=='Enter')return;event.preventDefault();publishButton.click();});
